CREATE TABLE iam_user_supplier_scope (
    user_id BIGINT NOT NULL,
    supplier_id BIGINT NOT NULL,
    created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    PRIMARY KEY (user_id, supplier_id),
