CREATE TABLE iam_inbound_business_projection (
    id BIGINT NOT NULL AUTO_INCREMENT,
    projection_type VARCHAR(64) NOT NULL,
    object_code VARCHAR(128) NOT NULL,
    source_system VARCHAR(64) NOT NULL,
    event_id VARCHAR(128) NOT NULL,
    event_type VARCHAR(128) NOT NULL,
    projection_status VARCHAR(32) NOT NULL,
    payload JSON NOT NULL,
    created_at DATETIME(3) NOT NULL,
    updated_at DATETIME(3) NOT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uk_iam_inbound_projection (projection_type, object_code),
    UNIQUE KEY uk_iam_inbound_projection_event (event_id),
    KEY idx_iam_inbound_projection_status (projection_type, projection_status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='IAM入站事件授权快照与处置待办';

